<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\{Access,Letters,Audit,Records};
class LetterController {
 public function index(Request $r){Access::menu('surat');$q=Letters::query();if($r->filled('q'))$q->where('w.nama','like','%'.mb_substr($r->string('q'),0,100).'%');if(in_array($r->status,['pending_rt','pending_rw','terbit']))$q->where('p.status',$r->status);return view('letters',['rows'=>$q->orderByDesc('p.id')->paginate(15)->withQueryString(),'archive'=>false]);}
 public function archive(Request $r){Access::menu('arsip');$q=Letters::query()->where('p.status','terbit');if($r->filled('q'))$q->where(function($x)use($r){$x->where('w.nama','like','%'.$r->q.'%')->orWhere('s.nomor_surat','like','%'.$r->q.'%');});return view('letters',['rows'=>$q->orderByDesc('p.id')->paginate(15)->withQueryString(),'archive'=>true]);}
 public function form(?int $id=null){Access::menu('surat',$id?'ubah':'tambah');$row=$id?Letters::get($id):null;if($row){abort_unless(auth()->user()->isAdmin()||auth()->user()->roleCode()==='RT'||(auth()->id()===$row->pemohon_id&&$row->status==='pending_rt'),403);abort_if($row->status==='terbit',422,'Surat sudah terbit. Cabut dokumen dan ajukan surat baru untuk koreksi isi resmi.');}return view('letter-form',['row'=>$row,'options'=>Records::options(),'types'=>DB::table('jenis_surat')->where('aktif',true)->whereNull('deleted_at')->get()]);}
 public function save(Request $r,?int $id=null){Access::menu('surat',$id?'ubah':'tambah');$old=$id?Letters::get($id):null;if($old){abort_unless($r->user()->isAdmin()||$r->user()->roleCode()==='RT'||(auth()->id()===$old->pemohon_id&&$old->status==='pending_rt'),403);abort_if($old->status==='terbit',422,'Isi surat terbit tidak diubah. Cabut lalu ajukan ulang.');}
  $v=$r->validate(['warga_id'=>'required|integer|exists:warga,id','jenis_surat_id'=>'required|integer|exists:jenis_surat,id','keperluan'=>'required|string|max:3000','isian'=>'nullable|array','isian.*'=>'nullable|string|max:1000']);$w=Access::warga((int)$v['warga_id']);abort_unless($w->status==='aktif'&&$w->rt_id,422,'Pemohon harus warga aktif yang memiliki KK/hunian.');$j=DB::table('jenis_surat')->whereNull('deleted_at')->where('aktif',true)->find($v['jenis_surat_id']);abort_unless($j,422,'Jenis surat tidak aktif.');
  $extra=match($j->kode){'USAHA'=>['isian.nama_usaha'=>'required|string|max:150','isian.jenis_usaha'=>'required|string|max:150','isian.alamat_usaha'=>'required|string|max:1000'],'NIKAH'=>['isian.nama_calon'=>'required|string|max:150','isian.nik_calon'=>'required|digits:16'],'KTP_KK'=>['isian.pengurusan'=>'required|in:KTP baru,KK baru,Perubahan KTP/KK'],'SKTM'=>['isian.tujuan_bantuan'=>'required|string|max:500'],default=>[]};$r->validate($extra);
  $v['isian']=json_encode(array_filter($v['isian']??[],fn($x)=>$x!==null&&$x!==''));$v['rt_id']=$w->rt_id;$v['updated_at']=now();
  DB::transaction(function()use($id,$old,$v){if($id){$locked=DB::table('permohonan_surat')->where('id',$id)->lockForUpdate()->first();abort_if($locked->status==='terbit',422,'Surat telah terbit.');DB::table('permohonan_surat')->where('id',$id)->update($v+['status'=>'pending_rt','revisi'=>$locked->revisi+1,'catatan_rt'=>null]);Audit::record('revisi','permohonan_surat',$id,$old,$v);}else{$new=DB::table('permohonan_surat')->insertGetId($v+['pemohon_id'=>auth()->id(),'status'=>'pending_rt','revisi'=>1,'diajukan_pada'=>now(),'created_at'=>now()]);Audit::record('ajukan','permohonan_surat',$new,null,$v);}});return redirect('/surat')->with('success','Permohonan tersimpan dan menunggu persetujuan RT.');
 }
 public function show(int $id){Access::menu('surat');$p=Letters::get($id);$history=DB::table('persetujuan_surat as s')->join('pengguna as u','u.id','=','s.pemeriksa_id')->where('s.permohonan_id',$id)->select('s.*','u.nama')->orderByDesc('s.id')->get();return view('letter-detail',compact('p','history'));}
 public function approve(Request $r,int $id){Access::menu('surat','ubah');Letters::get($id);$v=$r->validate(['status'=>'required|in:pending,approved','catatan'=>'nullable|string|max:2000']);Letters::approve($id,$v['status'],$v['catatan']??null);return redirect('/surat/'.$id)->with('success','Status persetujuan berhasil diperbarui.');}
 public function revoke(Request $r,int $id){abort_unless($r->user()->isAdmin(),403);$p=Letters::get($id);abort_unless($p->surat_id,404);DB::transaction(function()use($p){DB::table('surat_terbit')->where('id',$p->surat_id)->update(['dicabut_pada'=>now(),'updated_at'=>now()]);Audit::record('cabut','surat_terbit',$p->surat_id);});return back()->with('success','Surat dicabut. Verifikasi QR akan menunjukkan status tidak berlaku.');}
 public function destroy(int $id){abort_unless(auth()->user()->isAdmin(),403);$p=Letters::get($id);DB::transaction(function()use($p){DB::table('permohonan_surat')->where('id',$p->id)->update(['deleted_at'=>now(),'updated_at'=>now()]);if($p->surat_id)DB::table('surat_terbit')->where('id',$p->surat_id)->update(['dicabut_pada'=>now(),'deleted_at'=>now(),'updated_at'=>now()]);Audit::record('hapus_logis','permohonan_surat',$p->id,$p);});return redirect('/surat')->with('success','Permohonan dihapus dari daftar aktif dan surat terkait dicabut.');}
 public function verify(string $token){abort_unless(preg_match('/^[a-f0-9]{64}$/',$token),404);$s=DB::table('surat_terbit')->where('token_qr_hash',hash('sha256',$token))->first();abort_unless($s,404);$snapshot=json_decode($s->snapshot,true);$snapshot['nama']=implode(' ',array_map(fn($w)=>mb_substr($w,0,1).str_repeat('*',max(1,mb_strlen($w)-1)),explode(' ',$snapshot['nama'])));return view('verify',['s'=>$s,'snapshot'=>$snapshot]);}
}
